import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useSettings } from '../context/SettingsContext';

const navLinks = [
    { to: '/', label: 'Home' },
    { to: '/about', label: 'About Us' },
    { to: '/courses', label: 'Courses' },
    { to: '/services', label: 'Services' },
    { to: '/team', label: 'Team' },
    { to: '/portfolios', label: 'Portfolios' },
    { to: '/certificates', label: 'Certificates' },
    { to: '/contact', label: 'Contact' },
];

export default function Navbar() {
    const [scrolled, setScrolled] = useState(false);
    const [menuOpen, setMenuOpen] = useState(false);
    const { settings } = useSettings();
    const location = useLocation();

    useEffect(() => {
        const onScroll = () => setScrolled(window.scrollY > 20);
        window.addEventListener('scroll', onScroll);
        return () => window.removeEventListener('scroll', onScroll);
    }, []);

    useEffect(() => {
        setMenuOpen(false);
    }, [location]);

    return (
        <header
            style={{
                position: 'sticky',
                top: 0,
                zIndex: 900,
                background: scrolled ? 'rgba(10,23,51,0.96)' : 'rgba(10,23,51,0.85)',
                backdropFilter: 'blur(12px)',
                borderBottom: scrolled ? '1px solid rgba(255,255,255,0.08)' : '1px solid rgba(255,255,255,0.05)',
                transition: 'all 0.3s',
            }}
        >
            <div
                className="container"
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    height: 88,
                }}
            >
                <Link to="/" className="brand" aria-label={settings.companyName}>
                    <img src="/logo.png" alt={settings.companyName} />
                    <span className="brand-name">{settings.companyName}</span>
                </Link>

                <nav
                    className="nav-desktop"
                    style={{ display: 'flex', alignItems: 'center', gap: 4 }}
                >
                    {navLinks.map((l) => (
                        <Link
                            key={l.to}
                            to={l.to}
                            style={{
                                padding: '8px 14px',
                                borderRadius: 8,
                                fontSize: '0.92rem',
                                fontWeight: 500,
                                color:
                                    location.pathname === l.to ? '#2DD4BF' : 'rgba(255,255,255,0.82)',
                                background:
                                    location.pathname === l.to
                                        ? 'rgba(45,212,191,0.12)'
                                        : 'transparent',
                            }}
                        >
                            {l.label}
                        </Link>
                    ))}
                    <Link
                        to="/admissions"
                        className="btn btn-primary"
                        style={{ marginLeft: 12 }}
                    >
                        Enroll Now
                    </Link>
                </nav>

                <button
                    className="nav-toggle"
                    onClick={() => setMenuOpen(!menuOpen)}
                    style={{
                        display: 'none',
                        background: 'transparent',
                        color: '#fff',
                        fontSize: '1.6rem',
                    }}
                    aria-label="Toggle menu"
                >
                    ☰
                </button>
            </div>

            {menuOpen && (
                <div
                    className="nav-mobile"
                    style={{
                        background: '#0A1733',
                        borderTop: '1px solid rgba(255,255,255,0.08)',
                        padding: '12px 24px 20px',
                    }}
                >
                    {navLinks.map((l) => (
                        <Link
                            key={l.to}
                            to={l.to}
                            style={{
                                display: 'block',
                                padding: '12px 8px',
                                color: location.pathname === l.to ? '#2DD4BF' : 'rgba(255,255,255,0.82)',
                                borderBottom: '1px solid rgba(255,255,255,0.06)',
                            }}
                        >
                            {l.label}
                        </Link>
                    ))}
                    <Link
                        to="/admissions"
                        className="btn btn-primary"
                        style={{ marginTop: 14, width: '100%', justifyContent: 'center' }}
                    >
                        Enroll Now
                    </Link>
                </div>
            )}
        </header>
    );
}
